import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
var config=window.MKSK_CONFIG;
var supabase=null;
function el(id){return document.getElementById(id);}
function show(id){var ids=["login-view","reset-view","player-view","admin-view"];ids.forEach(function(x){var node=el(x);if(node){node.classList.toggle("hidden",x!==id);}});var logout=el("logout");if(logout){logout.classList.toggle("hidden",id==="login-view");}}
function numberValue(v){return Number(v||0);}
function playerHtml(label,value){return "<div class='metric'><span>"+label+"</span><strong>"+value+"</strong></div>";}
async function loadPlayer(playerId){var result=await supabase.from("players").select("*,player_season_stats(*)").is("archived_at",null).eq("id",playerId).single();if(result.error){throw result.error;}var p=result.data;if(p.access_disabled)throw new Error('Oyuncu erişiminiz yönetici tarafından kapatılmış.');var s=(p.player_season_stats||[]).find(x=>x.season===selectedSeason)||{};await loadTeamMatches();el("player-name").textContent=p.full_name;el("player-summary").innerHTML=playerHtml("Forma no",p.jersey_number||"—")+playerHtml("Mevki",p.position||"—")+playerHtml("Maç",numberValue(s.matches))+playerHtml("Puan",numberValue(s.points))+playerHtml("Kaçırdığı maç",missedMatches(s.matches))+playerHtml("Takımın maç sayısı",teamMatchCount);el("player-stats").innerHTML="<div class='stat'><span>Gol</span><strong>"+numberValue(s.goals)+"</strong></div><div class='stat'><span>Asist</span><strong>"+numberValue(s.assists)+"</strong></div><div class='stat'><span>Maçın adamı</span><strong>"+numberValue(s.man_of_match)+"</strong></div><div class='stat'><span>Başarı yüzdesi</span><strong>"+numberValue(s.success_rate)+"%</strong></div>";var report=el("player-report");if(!report){report=document.createElement("section");report.id="player-report";report.className="card";el("player-view").appendChild(report);}report.innerHTML="<h3>Yönetici raporu / mesajı</h3><p style='white-space:pre-wrap'>"+safe(p.player_note||"Henüz rapor yazılmadı.")+"</p>";await reportHistory(report,playerId,false);await playerMessageBox(playerId);renderPlayerPerformance(p);setupPlayerSections();show("player-view");await trackVisit();}
function safe(v){return String(v??"").replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
var statLabels={matches:'Maç sayısı',points:'Puan',goals:'Gol',assists:'Asist',man_of_match:'Maçın adamı',goals_conceded:'Yenilen gol',success_rate:'Başarı yüzdesi',attendance_matches:'ANTRENMAN SAYISI',attendance_goals:'ANT GOL SAYISI',attendance_points:'ANT PUANI',discipline_referrals:'Disiplin sevk'};
var performanceLabels=['Değerlendirilmedi','Süper yıldız','Çok iyi','Formda','Yükselişte','Gelişmesi gerekiyor','Formda değil'];
var displayStatLabels={...statLabels,missed_matches:'Kaçırdığı maç'},teamMatchCount=0,playerDashboardPage='stats';
var clubLogoPromise=null;
function loadClubLogo(){if(!clubLogoPromise)clubLogoPromise=new Promise((resolve,reject)=>{var image=new Image();image.onload=()=>resolve(image);image.onerror=()=>{clubLogoPromise=null;reject(new Error('Takım logosu yüklenemedi. Sayfayı yenileyip tekrar dene.'));};image.src=new URL('güncel logo.jfif',import.meta.url).href;});return clubLogoPromise;}
async function loadTeamMatches(){var r=await supabase.from('club_season_summary').select('matches').eq('season',selectedSeason).single();if(r.error)throw r.error;teamMatchCount=numberValue(r.data.matches);return teamMatchCount;}
function missedMatches(matches){return Math.max(0,teamMatchCount-numberValue(matches));}
function performanceBadge(label){var name=label||'Değerlendirilmedi',classes=['unrated','star','great','fit','rising','improve','unfit'];return '<span class="performance-badge '+(classes[performanceLabels.indexOf(name)]||'unrated')+'">'+safe(name)+'</span>';}
function goalSuggestions(position){var group=positionGroup({position});if(group==='GK')return ['Kurtarış ve refleks','Pozisyon alma','Yan toplar','Top dağıtma','Savunmayı yönlendirme','Bire bir pozisyonlar'];if(['STP','SGB','SLB'].includes(group))return ['Markaj','Kademe ve alan paylaşımı','İkili mücadele','Topu oyuna sokma','Pas tercihi','Hava topları'];if(group==='OS')return ['Pas tercihi','Oyun kurma','Top kontrolü','Pres ve top kazanma','Savunma desteği','Şut ve son pas'];if(['SGK','SLK'].includes(group))return ['Dripling','Orta kalitesi','Savunmaya dönüş','Topsuz hareket','Bitiricilik','Bire bir hücum'];if(group==='F')return ['Bitiricilik','Ceza sahasında pozisyon alma','Topsuz koşu','Hava topları','Önde pres','Takım arkadaşına pozisyon hazırlama'];return ['Top kontrolü','Pas kalitesi','Pozisyon bilgisi','Takım iletişimi','Maça ve antrenmana katılım'];}
function setupDevelopmentGoals(){document.querySelectorAll('.player-edit').forEach(f=>{var box=f.querySelector('.goal-presets');if(!box)return;function draw(){var suggestions=[...goalSuggestions(f.querySelector('[name=position]').value),'Takım iletişimi','Antrenman devamlılığı'];box.innerHTML='<p>Mevkiye uygun hedef önerileri. İstersen serbestçe de yazabilirsin.</p>'+[...new Set(suggestions)].map(label=>'<button type="button">'+safe(label)+'</button>').join('');box.querySelectorAll('button').forEach(b=>b.onclick=()=>{var field=f.querySelector('[name=development_goal]'),line=b.textContent;if(field.value.split('\n').some(v=>v.trim()===line))return;var updated=field.value.trim()+(field.value.trim()?'\n':'')+line;if(updated.length>2000)return;field.value=updated;field.dispatchEvent(new Event('input',{bubbles:true}));});}draw();f.querySelector('[name=position]').addEventListener('input',draw);});}
function renderPlayerPerformance(p){var box=el('player-performance');if(!box){box=document.createElement('section');box.id='player-performance';box.className='card';el('player-summary').before(box);}box.innerHTML='<h3>Performans durumum</h3>'+performanceBadge(p.performance_label)+'<h4>Gelişim hedeflerim / yönetici notu</h4><p class="development-text">'+safe(p.development_goal||'Yöneticin henüz bir gelişim hedefi yazmadı.')+'</p>';}
function setupPlayerSections(){var nav=el('player-nav');if(!nav){nav=document.createElement('nav');nav.id='player-nav';nav.className='dashboard-tabs';nav.setAttribute('aria-label','Oyuncu bölümleri');el('player-view').querySelector('.welcome').after(nav);}nav.innerHTML='<button type="button" data-player-page="stats">İstatistiklerim</button><button type="button" data-player-page="reports">Yönetici raporları</button><button type="button" class="player-message-tab" data-player-page="message">Yönetime mesaj</button>';nav.querySelectorAll('button').forEach(b=>b.onclick=()=>setPlayerPage(b.dataset.playerPage));setPlayerPage(playerDashboardPage);}
function setPlayerPage(page){playerDashboardPage=page;[['player-summary',page==='stats'],['player-performance',page==='stats'],['player-report',page==='reports'],['player-message-box',page==='message']].forEach(([id,visible])=>{if(el(id))el(id).hidden=!visible;});el('player-stats').closest('section').hidden=page!=='stats';if(el('season-controls'))el('season-controls').hidden=false;el('player-nav').querySelectorAll('button').forEach(b=>{b.classList.toggle('active',b.dataset.playerPage===page);b.setAttribute('aria-pressed',String(b.dataset.playerPage===page));});if(page==='message')el('player-message-box').querySelector('textarea').focus();}

function positionGroup(p){var k=String(p.position||'').trim().toLocaleUpperCase('tr-TR').replace(/Ğ/g,'G');if(k==='DOS'||k==='OOS')return 'OS';return k;}
function pinnedPlayer(p){return String(p.full_name||'').trim().toLocaleUpperCase('tr-TR')==='RAHMAN İSMAİL BENEK';}
function positionOrder(a,b){var pin=Number(pinnedPlayer(b))-Number(pinnedPlayer(a));if(pin)return pin;var groups=['GK','STP','SGB','SLB','OS','SGK','SLK','F'];var ia=groups.indexOf(positionGroup(a)),ib=groups.indexOf(positionGroup(b));if(ia<0)ia=99;if(ib<0)ib=99;var na=a.jersey_number==null||a.jersey_number===''?9999:Number(a.jersey_number),nb=b.jersey_number==null||b.jersey_number===''?9999:Number(b.jersey_number);return ia-ib||na-nb||String(a.full_name).localeCompare(String(b.full_name),'tr');}

async function teamSummary(players){var r=await supabase.from('club_season_summary').select('matches').eq('season',selectedSeason).single();if(r.error)throw r.error;teamMatchCount=numberValue(r.data.matches);var totals=await supabase.from('player_season_stats').select('goals,goals_conceded').eq('season',selectedSeason);if(totals.error)throw totals.error;var sum=k=>(totals.data||[]).reduce((a,s)=>a+numberValue(s[k]),0);var box=el('team-summary');if(!box){box=document.createElement('section');box.id='team-summary';box.className='card';el('roster').after(box);}box.innerHTML='<h3>MECİDİYE KARAHİSAR SPOR KULÜBÜ — Genel istatistikler</h3><div class="summary-grid">'+playerHtml('Toplam maç',r.data.matches)+playerHtml('Toplam gol',sum('goals'))+playerHtml('Yenilen gol',sum('goals_conceded'))+'</div><p>Gol toplamları oyuncu sezon kayıtlarından hesaplanır.</p><form id="team-matches-form"><label>Takımın maç sayısı<input name="matches" type="number" min="0" step="1" required value="'+r.data.matches+'"></label><button type="submit">Maç sayısını kaydet</button><p class="team-message"></p></form>';el('team-matches-form').onsubmit=async e=>{e.preventDefault();var b=e.target.querySelector('button'),n=Number(new FormData(e.target).get('matches'));if(!Number.isInteger(n)||n<0)return;b.disabled=true;var q=await supabase.from('club_season_summary').update({matches:n}).eq('season',selectedSeason);e.target.querySelector('.team-message').textContent=q.error?'Kaydedilemedi: '+q.error.message:'Maç sayısı kaydedildi.';b.disabled=false;if(!q.error){await teamSummary(players);applyFilters();}};}

function setupFilters(players){var box=el('roster-filters');if(!box){box=document.createElement('section');box.id='roster-filters';box.className='card';el('roster').before(box);box.innerHTML='<h3>Oyuncu filtreleri</h3><div class="stats-form"><label>Mevki<select data-filter="position"></select></label><label>Oyuncunun grubu<select data-filter="group_name"></select></label><label>Yönetim görevi<select data-filter="management_role"></select></label><label>Oyuncu durumu<select data-filter="status"></select></label><label>Performans durumu<select data-filter="performance_label"></select></label><label>Sistem erişimi<select id="filter-access"><option value="">Tümü</option><option value="open">Açık</option><option value="closed">Kapalı</option></select></label><label>Hesap yetkisi<select id="filter-role"><option value="">Tümü</option><option value="admin">Yönetici</option><option value="player">Oyuncu</option><option value="unlinked">Hesap bağlı değil</option></select></label><label>İstatistik<select id="filter-stat"><option value="">İstatistik seç</option>'+Object.entries(displayStatLabels).map(([k,l])=>'<option value="'+k+'">'+l+'</option>').join('')+'</select></label><label>En az<input id="filter-min" type="number" step="any"></label><label>En çok<input id="filter-max" type="number" step="any"></label></div><button id="clear-filters" type="button">Filtreleri temizle</button><p id="filter-count" aria-live="polite"></p>';box.querySelectorAll('select,input').forEach(e=>e.addEventListener('input',applyFilters));el('clear-filters').onclick=()=>{box.querySelectorAll('select,input').forEach(e=>e.value='');el('search').value='';applyFilters();};el('search').placeholder='Ad veya forma numarası ara';el('search').addEventListener('input',applyFilters);}box.querySelectorAll('[data-filter]').forEach(select=>{var prev=select.value,k=select.dataset.filter,values=k==='performance_label'?performanceLabels:[...new Set(players.map(p=>k==='position'?positionGroup(p):String(p[k]||'').trim()))].sort((a,b)=>a.localeCompare(b,'tr'));select.innerHTML='<option value="">Tümü</option>'+values.map(v=>'<option value="'+safe(v||'__empty__')+'">'+safe(v||'Belirtilmemiş')+'</option>').join('');if([...select.options].some(o=>o.value===prev))select.value=prev;});applyFilters();}
function applyFilters(){var box=el('roster-filters');if(!box)return;var query=el('search').value.trim().toLocaleLowerCase('tr'),metric=el('filter-stat').value,min=el('filter-min').value,max=el('filter-max').value,count=0,matched=[];document.querySelectorAll('.player-edit').forEach(f=>{var match=(f.querySelector('[name=full_name]').value+' '+f.querySelector('[name=jersey_number]').value).toLocaleLowerCase('tr').includes(query);box.querySelectorAll('[data-filter]').forEach(s=>{if(!s.value)return;var v=f.querySelector('[name='+s.dataset.filter+']').value.trim();if(s.dataset.filter==='position')v=positionGroup({position:v});if((v||'__empty__')!==s.value)match=false;});var access=el('filter-access').value,role=el('filter-role').value;if(access&&(f.dataset.disabled==='true'?'closed':'open')!==access)match=false;if(role&&(accountRoles[f.dataset.id]||'unlinked')!==role)match=false;if(metric){var n=metric==='missed_matches'?missedMatches(f.querySelector('[name=matches]').value):Number(f.querySelector('[name='+metric+']').value||0);if(min!==''&&n<Number(min))match=false;if(max!==''&&n>Number(max))match=false;}var pinned=pinnedPlayer({full_name:f.querySelector('[name=full_name]').value});f.dataset.outsideFilter=String(pinned&&!match);f.closest('article').hidden=(!match&&!pinned)||!f.closest('article').classList.contains('editing');if(match){count++;matched.push(f);}else if(pinned)matched.unshift(f);});el('filter-count').textContent=count+' oyuncu filtreye uyuyor.'+(matched.some(f=>f.dataset.outsideFilter==='true')?' RAHMAN İSMAİL BENEK sabit satır olarak ayrıca gösterilir.':'')+' Takım özeti tüm kadroyu kapsar.';renderRosterList(matched);}
function compactCards(){document.querySelectorAll('.player-edit').forEach(f=>{var heading=f.querySelector('h3'),info=document.createElement('p'),details=document.createElement('details'),summary=document.createElement('summary'),body=document.createElement('div');details.className='data-entry';body.className='data-entry-body';summary.textContent='Oyuncuyu düzenle';summary.style.cssText='cursor:pointer;background:#173f72;color:white;border-left:5px solid #f6db31;border-radius:8px;padding:12px;font-weight:700';function update(){info.textContent='Forma: '+(f.querySelector('[name=jersey_number]').value||'—')+' · Mevki: '+(f.querySelector('[name=position]').value||'Belirtilmemiş');heading.textContent=f.querySelector('[name=full_name]').value;}Array.from(f.children).filter(n=>n!==heading).forEach(n=>body.appendChild(n));var close=document.createElement('button');close.type='button';close.textContent='Düzenlemeyi kapat';close.onclick=()=>{f.closest('article').classList.remove('editing');f.closest('article').hidden=true;el('roster-list').scrollIntoView({behavior:'smooth'});};body.appendChild(close);details.append(summary,body);f.append(info,details);update();f.addEventListener('input',update);details.addEventListener('toggle',()=>{if(details.open)document.querySelectorAll('.data-entry').forEach(other=>{if(other!==details)other.open=false;});});});}

var selectedSeason='2026-2027',canManageRoles=false,accountRoles={},activeRole=null;
async function setupSeasons(isAdmin){var r=await supabase.from('club_season_summary').select('season').order('season',{ascending:false});if(r.error)throw r.error;var box=el('season-controls');if(!box){box=document.createElement('section');box.id='season-controls';box.className='card';document.querySelector('.topbar').after(box);}box.innerHTML='<label>Sezon seç<select id="season-select">'+(r.data||[]).map(s=>'<option value="'+safe(s.season)+'">'+safe(s.season)+'</option>').join('')+'</select></label>'+(isAdmin?'<details><summary>Yeni sezon oluştur</summary><p>Mevcut sezon silinmez. Kadro korunur; yeni sezonun istatistikleri sıfırdan başlar.</p><form id="new-season-form"><label>Sezon adı<input name="season" placeholder="2027-2028" pattern="[0-9]{4}-[0-9]{4}" required></label><button type="submit">Yeni sezonu oluştur</button><p id="season-message"></p></form></details>':'');el('season-select').value=selectedSeason;el('season-label').textContent=selectedSeason+' Sezonu';el('season-select').onchange=async e=>{selectedSeason=e.target.value;el('season-label').textContent=selectedSeason+' Sezonu';try{await refresh();}catch(x){el('login-error').textContent=x.message;}};if(isAdmin)el('new-season-form').onsubmit=async e=>{e.preventDefault();var name=new FormData(e.target).get('season').trim(),parts=name.split('-').map(Number),msg=el('season-message'),b=e.target.querySelector('button');if(!/^\d{4}-\d{4}$/.test(name)||parts[1]!==parts[0]+1){msg.textContent='Sezonu 2027-2028 gibi ardışık iki yıl olarak yaz.';return;}b.disabled=true;var q=await supabase.from('club_season_summary').insert({season:name,matches:0});if(q.error){msg.textContent=q.error.code==='23505'?'Bu sezon zaten var.':q.error.message;b.disabled=false;return;}await setupSeasons(true);el('season-controls').insertAdjacentHTML('beforeend','<p>Yeni sezon oluşturuldu. '+safe(selectedSeason)+' seçili kaldı. Yeni sezona geçmek için listeden seç.</p>');};}

var inviteToken=new URLSearchParams(location.hash.slice(1)).get('davet')||sessionStorage.getItem('pending-player-invite')||'';if(inviteToken){sessionStorage.setItem('pending-player-invite',inviteToken);if(location.hash.startsWith('#davet='))history.replaceState(null,'',location.pathname+location.search);}
async function claimInvite(){if(!inviteToken)return;var r=await supabase.rpc('accept_player_invite',{invite_token:inviteToken});if(r.error)throw r.error;inviteToken='';sessionStorage.removeItem('pending-player-invite');}
function inviteLoginUi(){if(!inviteToken)return;var note=document.createElement('p');note.textContent='Kişisel oyuncu daveti: kendi e-posta ve şifrenle giriş yap. Hesabın yoksa aşağıdan oluştur. Giriş sayısı, son giriş ve yaklaşık aktif kullanım süresi yöneticiler tarafından görülebilir.';el('login-form').prepend(note);var b=document.createElement('button');b.type='button';b.textContent='Davetle oyuncu hesabı oluştur';b.onclick=async()=>{var email=el('email').value.trim(),password=el('password').value;if(!email||password.length<8){el('login-error').textContent='Geçerli e-posta ve en az 8 karakter şifre gir.';return;}b.disabled=true;try{var r=await supabase.auth.signUp({email,password});if(r.error)throw r.error;if(r.data.session){await claimInvite();await refresh();}else el('login-error').textContent='E-posta onayı gerekiyorsa gelen kutunu kontrol et. Ardından bu davet bağlantısını yeniden açıp giriş yap.';}catch(e){el('login-error').textContent=e.message;}finally{b.disabled=false;}};el('login-form').appendChild(b);}
async function accountTools(){document.querySelectorAll('.player-edit').forEach(f=>{var body=f.querySelector('.data-entry-body'),b=document.createElement('button'),result=document.createElement('div');b.type='button';b.textContent='Kişisel davet bağlantısı oluştur';b.onclick=async()=>{b.disabled=true;result.textContent='Davet hazırlanıyor...';var r=await supabase.rpc('create_player_invite',{target_player:f.dataset.id});if(r.error){result.textContent=r.error.message;b.disabled=false;return;}result.textContent='7 gün geçerli, tek kullanımlık. Yalnızca bu oyuncuya özelden gönder. Yeni davet eski kullanılmamış bağlantıyı iptal eder.';var input=document.createElement('input');input.readOnly=true;input.value=location.origin+location.pathname+'#davet='+encodeURIComponent(r.data);input.setAttribute('aria-label','Kişisel davet bağlantısı');var copy=document.createElement('button');copy.type='button';copy.textContent='Bağlantıyı kopyala';copy.onclick=async()=>{try{await navigator.clipboard.writeText(input.value);copy.textContent='Kopyalandı';}catch(e){input.select();copy.textContent='Bağlantıyı seçip kopyalayabilirsin';}};result.append(input,copy);b.disabled=false;};body.append(b,result);});var panel=el('visit-panel');if(!panel){panel=document.createElement('section');panel.id='visit-panel';panel.className='card';el('team-summary').after(panel);}panel.innerHTML='<h3>Oyuncu giriş geçmişi</h3><p>Giriş sayısı oturum açılışlarını gösterir; sayfa yenileme de yeni oturum sayılabilir. Süre yalnızca açık ve aktif sayfadan yaklaşık ölçülür.</p><button type="button">Giriş geçmişini yenile</button><div class="visit-results"></div>';panel.querySelector('button').onclick=async()=>{var box=panel.querySelector('.visit-results');box.textContent='Yükleniyor...';var r=await supabase.from('player_visit_sessions').select('player_id,started_at,last_seen,active_seconds').order('started_at',{ascending:false}).limit(5000);if(r.error){box.textContent=r.error.message;return;}var totals={};r.data.forEach(s=>{var a=totals[s.player_id]||(totals[s.player_id]={count:0,seconds:0,last:s.started_at});a.count++;a.seconds+=s.active_seconds;});box.innerHTML='';document.querySelectorAll('.player-edit').forEach(f=>{var a=totals[f.dataset.id],p=document.createElement('article');p.className='visit-card';p.innerHTML='<div class="visit-card-title"><strong>'+safe(f.querySelector('[name=full_name]').value)+'</strong><span class="visit-count">'+(a?a.count:0)+' giriş</span></div><div class="visit-metrics"><div><span>Aktif kullanım</span><strong>'+(a?Math.floor(a.seconds/60)+' dk '+a.seconds%60+' sn':'—')+'</strong></div><div><span>Son giriş</span><strong>'+(a?safe(new Date(a.last).toLocaleString('tr-TR',{timeZone:'Europe/Istanbul'})):'Henüz giriş yok')+'</strong></div></div>';box.appendChild(p);});};}
var visitId=null,visitTimer=null,lastActivity=Date.now();['pointerdown','keydown','scroll','touchstart'].forEach(event=>document.addEventListener(event,()=>lastActivity=Date.now(),{passive:true}));
async function trackVisit(){if(window.MKSK_PLAYER_PREVIEW||visitId)return;var r=await supabase.rpc('start_player_visit');if(r.error||!r.data)return;visitId=r.data;var notice=document.createElement('p');notice.textContent='Giriş sayısı, son giriş ve yaklaşık aktif kullanım süren yöneticiler tarafından görülebilir.';el('player-view').prepend(notice);visitTimer=setInterval(async()=>{var access=await supabase.rpc('player_access_allowed');if(!access.error&&!access.data){clearInterval(visitTimer);visitTimer=null;visitId=null;await supabase.auth.signOut();show('login-view');el('player-name').textContent='';el('player-summary').innerHTML='';el('player-stats').innerHTML='';if(el('player-report'))el('player-report').innerHTML='';el('login-error').textContent='Oyuncu erişiminiz yönetici tarafından kapatılmış.';return;}if(document.visibilityState==='visible'&&Date.now()-lastActivity<60000){var tick=await supabase.rpc('tick_player_visit',{session_id:visitId});if(tick.error)console.warn('Aktif kullanım süresi güncellenemedi:',tick.error.message);}},30000);}
async function loadAdmin(){var r=await supabase.from('players').select('*,player_season_stats(*)').is('archived_at',null).order('full_name');if(r.error)throw r.error;var owner=await supabase.rpc('is_club_owner');if(owner.error)throw owner.error;canManageRoles=Boolean(owner.data);var roles=await supabase.rpc('player_account_roles');if(roles.error)throw roles.error;accountRoles={};(roles.data||[]).forEach(p=>accountRoles[p.player_id]=p.role);el('roster').innerHTML=(r.data||[]).sort(positionOrder).map(function(p){var s=(p.player_season_stats||[]).find(x=>x.season===selectedSeason)||{};return '<article class="player-row"><form class="player-edit" data-id="'+p.id+'" data-disabled="'+Boolean(p.access_disabled)+'"><h3>'+safe(p.full_name)+'</h3><label>Yönetim görevi<input name="management_role" value="'+safe(p.management_role)+'"></label><label>Oyuncunun grubu<input name="group_name" value="'+safe(p.group_name)+'"></label><label>Ad soyad<input name="full_name" required value="'+safe(p.full_name)+'"></label><label>Forma no<input name="jersey_number" type="number" min="0" value="'+safe(p.jersey_number)+'"></label><label>Mevki<input name="position" placeholder="Mevki gir" value="'+safe(p.position)+'"></label><label>Oyuncu durumu<input name="status" value="'+safe(p.status||'Aktif')+'"></label><label>Performans durumu<select name="performance_label">'+performanceLabels.map(label=>'<option value="'+safe(label)+'" '+(label===(p.performance_label||'Değerlendirilmedi')?'selected':'')+'>'+safe(label)+'</option>').join('')+'</select></label><label>Gelişim hedefi / yönetici notu<textarea name="development_goal" rows="4" maxlength="2000" placeholder="Bu oyuncunun çalışması gereken hedefleri yaz">'+safe(p.development_goal||'')+'</textarea></label><div class="goal-presets"></div><h4>Maç ve antrenman istatistikleri</h4><div class="stats-form">'+Object.entries(statLabels).map(([k,l])=>'<label>'+l+'<input name="'+k+'" type="number" min="0" '+(k==='success_rate'?'max="100" step="0.1"':'step="1"')+' value="'+numberValue(s[k])+'"></label>').join('')+'</div><label>Yeni rapor / yönetici mesajı<textarea name="player_note" rows="4" maxlength="10000" placeholder="Oyuncuya raporunu veya mesajını yaz">'+safe('')+'</textarea></label><button type="submit">Değişiklikleri kaydet</button><p class="save-message" aria-live="polite"></p><button type="button" class="history-button">Rapor geçmişi / çöp kutusu</button><div class="report-history"></div></form></article>';}).join('');el('roster').querySelectorAll('.player-edit').forEach(f=>f.addEventListener('submit',savePlayer));el('roster').querySelectorAll('.history-button').forEach(b=>b.onclick=()=>{var f=b.closest('form');reportHistory(f.querySelector('.report-history'),f.dataset.id,true);});el('add-player-form').onsubmit=addPlayer;await teamSummary(r.data||[]);compactCards();setupDevelopmentGoals();setupFilters(r.data||[]);await accountTools();await adminInbox();setupDashboardSections();show('admin-view');}
async function savePlayer(e){e.preventDefault();var f=e.target,msg=f.querySelector('.save-message'),button=f.querySelector('button[type=submit]'),d=new FormData(f);button.disabled=true;msg.textContent='Kaydediliyor...';try{var p={full_name:d.get('full_name').trim(),jersey_number:d.get('jersey_number')===''?null:Number(d.get('jersey_number')),position:d.get('position').trim()||null,status:d.get('status').trim()||'Aktif',group_name:d.get('group_name').trim()||null,management_role:d.get('management_role').trim()||null,performance_label:d.get('performance_label')||'Değerlendirilmedi',development_goal:String(d.get('development_goal')||'').trim()},s={};Object.keys(statLabels).forEach(k=>s[k]=numberValue(d.get(k)));var r=await supabase.rpc('club_save_player',{p_id:f.dataset.id,p_season:selectedSeason,p_player:p,p_stats:s});if(r.error)throw r.error;await saveNewReport(f.dataset.id,d.get('player_note')||'');f.querySelector('[name=player_note]').value='';var all=await supabase.from('players').select('*,player_season_stats(*)').is('archived_at',null);if(!all.error){await teamSummary(all.data||[]);setupFilters(all.data||[]);}msg.textContent='Bilgiler kaydedildi. Yeni rapor geçmişe eklendi.';applyFilters();}catch(x){msg.textContent='Kaydedilemedi: '+x.message;}finally{button.disabled=false;}}
async function addPlayer(e){e.preventDefault();var f=e.target,d=new FormData(f),b=f.querySelector('button');b.disabled=true;el('admin-message').textContent='Oyuncu ekleniyor...';try{var r=await supabase.from('players').insert({full_name:d.get('full_name').trim(),jersey_number:d.get('jersey_number')===''?null:Number(d.get('jersey_number')),position:d.get('position').trim()||null,status:'Aktif',birth_date:d.get('birth_date')||null,joined_at:d.get('joined_at')||null,join_year:d.get('joined_at')?Number(String(d.get('joined_at')).slice(0,4)):d.get('join_year')?Number(d.get('join_year')):null});if(r.error)throw r.error;f.reset();await loadAdmin();el('admin-message').textContent='Oyuncu eklendi. İstatistiklerini aşağıdan girebilirsin.';}catch(x){el('admin-message').textContent='Oyuncu eklenemedi: '+x.message;}finally{b.disabled=false;}}
async function refresh(){var userResult=await supabase.auth.getUser();var user=userResult.data.user;if(!user){show("login-view");return;}var profileResult=await supabase.from("profiles").select("role,player_id").eq("id",user.id).single();if(profileResult.error){throw new Error("Bu hesap için yetki kaydı bulunamadı.");}if(profileResult.data.role!=="admin"){var access=await supabase.rpc("player_access_allowed");if(access.error)throw access.error;if(!access.data){await supabase.auth.signOut();show("login-view");throw new Error("Oyuncu erişiminiz yönetici tarafından kapatılmış.");}}activeRole=profileResult.data.role;await setupSeasons(profileResult.data.role==="admin");if(profileResult.data.role==="admin"){await loadAdmin();}else{el("roster").innerHTML="";if(el("roster-list"))el("roster-list").innerHTML="";await loadPlayer(profileResult.data.player_id);}}
async function start(){try{if(!config||!config.supabaseUrl||!config.supabaseAnonKey){throw new Error("Bağlantı ayarları eksik.");}supabase=createClient(config.supabaseUrl,config.supabaseAnonKey);window.MKSK_DB=supabase;inviteLoginUi();el("login-form").addEventListener("submit",async function(event){event.preventDefault();el("login-error").textContent="Giriş kontrol ediliyor...";var response=await supabase.auth.signInWithPassword({email:el("email").value.trim(),password:el("password").value});if(response.error){el("login-error").textContent="E-posta veya şifre hatalı.";return;}try{await claimInvite();await refresh();}catch(error){el("login-error").textContent=error.message||"Giriş açılırken hata oluştu.";}});el("logout").addEventListener("click",async function(){if(visitTimer)clearInterval(visitTimer);visitTimer=null;visitId=null;await supabase.auth.signOut();show("login-view");});await refresh();}catch(error){el("login-error").textContent="Uygulama başlatılamadı: "+error.message;show("login-view");}}

async function saveNewReport(playerId,body){if(!body.trim())return;var u=(await supabase.auth.getUser()).data.user;var p=await supabase.from('profiles').select('player_id').eq('id',u.id).single();var name='Yönetici';if(p.data?.player_id){var who=await supabase.from('players').select('full_name').eq('id',p.data.player_id).single();name=who.data?.full_name||name;}var r=await supabase.from('player_report_history').insert({player_id:playerId,body:body.trim(),author_id:u.id,author_name:name});if(r.error)throw r.error;}
async function reportHistory(box,playerId,isAdmin){box.textContent='Raporlar yükleniyor...';var r=await supabase.from('player_report_history').select('*').eq('player_id',playerId).order('created_at',{ascending:false});if(r.error){box.textContent='Raporlar açılamadı: '+r.error.message;return;}var rows=r.data||[];box.innerHTML='<h4>Rapor geçmişi</h4><div class="active-reports"></div>'+(isAdmin?'<details><summary>Çöp kutusu</summary><div class="trash-reports"></div></details>':'');for(var h of rows){var target=box.querySelector(h.deleted_at?'.trash-reports':'.active-reports');if(!target)continue;var item=document.createElement('article');item.style.cssText='background:#e6f3ff;border-left:4px solid #edce37;padding:12px;margin:10px 0;border-radius:8px';var meta=document.createElement('small');meta.textContent=new Date(h.created_at).toLocaleString('tr-TR',{timeZone:'Europe/Istanbul'})+' · '+h.author_name;item.appendChild(meta);var body=document.createElement('p');body.textContent=h.body;body.style.whiteSpace='pre-wrap';item.appendChild(body);if(isAdmin){if(!h.deleted_at){var edit=document.createElement('button');edit.type='button';edit.textContent='Düzenle';edit.onclick=function(record,node){return function(){var t=document.createElement('textarea');t.value=record.body;t.rows=4;var save=document.createElement('button');save.type='button';save.textContent='Rapor değişikliğini kaydet';save.onclick=async function(){if(!t.value.trim())return;save.disabled=true;var q=await supabase.from('player_report_history').update({body:t.value.trim(),updated_at:new Date().toISOString()}).eq('id',record.id);if(q.error){save.disabled=false;alert(q.error.message);}else await reportHistory(box,playerId,true);};node.append(t,save);this.disabled=true;};}(h,item);item.appendChild(edit);}var action=document.createElement('button');action.type='button';action.textContent=h.deleted_at?'Geri al':'Çöp kutusuna taşı';action.onclick=function(record){return async function(){this.disabled=true;var q=await supabase.from('player_report_history').update({deleted_at:record.deleted_at?null:new Date().toISOString(),updated_at:new Date().toISOString()}).eq('id',record.id);if(q.error){this.disabled=false;alert(q.error.message);}else await reportHistory(box,playerId,true);};}(h);item.appendChild(action);}target.appendChild(item);}if(!rows.some(h=>!h.deleted_at))box.querySelector('.active-reports').textContent='Henüz rapor bulunmuyor.';}

